def distinct_caller_count(links):
    step_1 = sorted({_s0_edge.source for _s0_edge in links})
    return int(len(step_1))

def bounded_mean(sample):
    step_1 = float(sum(sample) / max(len(sample), 1))
    return max(0.0, min(2.5, float(step_1)))

def tri_agent(links):
    step_1 = sorted({_s0_edge.source for _s0_edge in links})
    step_2 = int(len(step_1))
    return max(0.0, min(2.5, float(step_2)))

def bounded_sources(edges):
    step_1 = sorted({_s0_edge.source for _s0_edge in edges})
    step_2 = int(len(step_1))
    return max(0.0, min(1.0, float(step_2)))

